<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
$pageTitle='Daily Journal';
$date=(string)($_GET['date']??date('Y-m-d')); $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
if(!$dt || $dt->format('Y-m-d')!==$date){$dt=new DateTimeImmutable('today');$date=$dt->format('Y-m-d');}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$editing=null;
if($editId){$st=$pdo->prepare('SELECT * FROM daily_entries WHERE id=?');$st->execute([$editId]);$editing=$st->fetch()?:null;if($editing){$date=$editing['entry_date'];$dt=new DateTimeImmutable($date);}}
$st=$pdo->prepare('SELECT * FROM daily_entries WHERE entry_date=? ORDER BY created_at DESC');$st->execute([$date]);$entries=$st->fetchAll();
$allCount=(int)$pdo->query('SELECT COUNT(*) FROM daily_entries')->fetchColumn();
$categories=['Personal','Work','Fitness','Entertainment','Family','Travel','Reflection','Other'];$moods=['Happy','Calm','Productive','Excited','Tired','Stressed','Sad','Grateful','Mixed'];
include __DIR__.'/../includes/header.php';
?>
<section class="module-heading"><div><p class="eyebrow">A LITTLE SPACE TO REFLECT</p><h1>Daily <em>journal.</em></h1><p class="module-intro">Capture the moments, thoughts and little wins that make up your days.</p></div><a class="btn btn-outline" href="calendar.php?month=<?=e($dt->format('Y-m'))?>">▦ Open calendar</a></section>
<section class="media-stats journal-stats"><article class="stat-card"><div class="stat-top"><span class="stat-icon">✎</span><span class="stat-label">TOTAL ENTRIES</span></div><div class="stat-value"><?=$allCount?></div><div class="stat-foot">Your personal pages</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon">▦</span><span class="stat-label">SELECTED DATE</span></div><div class="stat-value journal-date-stat"><?=e($dt->format('d'))?></div><div class="stat-foot"><?=e($dt->format('F Y'))?></div></article></section>
<div class="journal-layout"><section class="panel journal-form-panel"><div class="panel-heading"><div><p class="eyebrow"><?=$editing?'UPDATE A MEMORY':'SAVE THIS MOMENT'?></p><h2><?=$editing?'Edit entry':'New journal entry'?></h2></div></div>
<form action="../actions/journal-save.php" method="post" class="form-stack"><?=csrf_field()?><?php if($editing):?><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><?php endif;?>
<label>Date<input type="date" name="entry_date" required value="<?=e($date)?>"></label><label>Title<input name="title" maxlength="160" required value="<?=e($editing['title']??'')?>" placeholder="What happened today?"></label>
<div class="form-row"><label>Category<select name="category"><?php foreach($categories as $c):?><option <?=($editing['category']??'Personal')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label>Mood <span class="muted">(optional)</span><select name="mood"><option value="">Choose mood</option><?php foreach($moods as $m):?><option <?=($editing['mood']??'')===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></label></div>
<label>Your notes <span class="muted">(optional)</span><textarea name="body" rows="7" maxlength="10000" placeholder="Write freely. This space is yours."><?=e($editing['body']??'')?></textarea></label><div class="modal-actions"><?php if($editing):?><a class="btn btn-outline" href="journal.php?date=<?=e($date)?>">Cancel</a><?php endif;?><button class="btn btn-gold" type="submit"><?=$editing?'Save changes':'Save entry'?></button></div></form></section>
<section class="panel journal-entries-panel"><div class="media-toolbar"><div><p class="eyebrow">YOUR NOTES</p><h2><?=e($dt->format('l, d F Y'))?></h2></div><div class="journal-date-nav"><a class="btn btn-outline btn-small" href="journal.php?date=<?=e($dt->modify('-1 day')->format('Y-m-d'))?>" aria-label="Previous day">‹</a><a class="btn btn-outline btn-small" href="journal.php?date=<?=e(date('Y-m-d'))?>">Today</a><a class="btn btn-outline btn-small" href="journal.php?date=<?=e($dt->modify('+1 day')->format('Y-m-d'))?>" aria-label="Next day">›</a></div></div>
<?php if(!$entries):?><div class="empty-state"><div class="empty-icon">✎</div><h3>A fresh page.</h3><p>No entries for this date yet. Add a note, a memory or a small win.</p></div><?php else:?><div class="journal-entry-list"><?php foreach($entries as $entry):?><article class="journal-entry"><div class="journal-entry-top"><span class="journal-category"><?=e($entry['category'])?></span><?php if($entry['mood']):?><span class="journal-mood">☼ <?=e($entry['mood'])?></span><?php endif;?></div><h3><?=e($entry['title'])?></h3><?php if($entry['body']):?><p><?=nl2br(e($entry['body']))?></p><?php endif;?><div class="journal-entry-actions"><small>Saved <?=e(date('H:i',strtotime($entry['created_at'])))?></small><a class="btn btn-outline btn-small" href="journal.php?date=<?=e($date)?>&edit=<?=(int)$entry['id']?>">✎ Edit</a><form action="../actions/journal-remove.php" method="post" data-confirm="Remove this journal entry? This cannot be undone."><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$entry['id']?>"><input type="hidden" name="entry_date" value="<?=e($date)?>"><button class="btn btn-danger-outline btn-small" type="submit">× Remove</button></form></div></article><?php endforeach;?></div><?php endif;?></section></div>
<?php include __DIR__.'/../includes/footer.php';?>
